131|function delay(ms: number): Promise<void> {
132|  return new Promise(resolve => setTimeout(resolve, ms))
133|}
134|
135|function cacheLimitBytes(): number {
136|  const raw = Number(process.env.HERMES_WORKSTATION_BROWSER_CACHE_MAX_MB ?? DEFAULT_CACHE_MAX_MB)
137|  const mb = Number.isFinite(raw) && raw > 32 ? raw : DEFAULT_CACHE_MAX_MB
138|  return Math.round(mb * 1024 * 1024)
139|}
140|
141|function backgroundFrameRate(): number {
142|  const raw = Number(process.env.HERMES_WORKSTATION_BROWSER_BACKGROUND_FPS ?? DEFAULT_BACKGROUND_FRAME_RATE)
143|  if (!Number.isFinite(raw)) return DEFAULT_BACKGROUND_FRAME_RATE
144|  return Math.max(1, Math.min(30, Math.round(raw)))
145|}
